SELECT ?zone ?zoneName ?ts WHERE {
  ?p brick:hasPropertyType brick:AirTemperature .
  ?p brick:isPointOf ?zone .
  ?zone a brick:Zone .
  OPTIONAL { ?p rdfs:label ?zoneName }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?a ?b (COUNT(*) AS ?n) WHERE {
  ?s ?a ?b
} GROUP BY ?a ?b ORDER BY ?n LIMIT 50

SELECT ?point ?cls ?zone ?label WHERE {
  ?point a ?cls .
  FILTER(str(?cls) LIKE "%Temperature%")
  ?z brick:hasPoint ?point .
  FILTER(str(?z) LIKE "%Zone%")
  OPTIONAL { ?z rdfs:label ?label }
}

SELECT ?point ?cls ?zone ?label WHERE {
  ?point a ?cls .
  ?z brick:hasPoint ?point .
  FILTER(str(?cls) LIKE "%Temperature%")
  FILTER(str(?z) LIKE "%Zone%")
  OPTIONAL { ?z rdfs:label ?label }
  BIND(?z AS ?zone)
}

SELECT ?point ?cls ?z ?label WHERE {
  ?z brick:hasPoint ?point .
  ?point a ?cls .
  ?point a brick:AirTemperatureSensor .
  OPTIONAL { ?z rdfs:label ?label }
}

SELECT DISTINCT ?cls WHERE {
  ?z brick:hasPoint ?point .
  ?point a ?cls .
  FILTER(str(?z) LIKE "%Zone%")
}

SELECT DISTINCT ?cls WHERE {
  ?z brick:hasPoint ?point .
  ?point a brick:AirTemperatureSensor .
  ?point a ?cls .
}

SELECT ?zone ?zoneName ?ts WHERE {
  ?z brick:hasPoint ?p .
  ?p a brick:AirTemperatureSensor .
  ?z rdfs:label ?zoneName .
  ?p ref:hasTimeseriesId ?ts .
}

SELECT ?zoneName ?ts ?p WHERE {
  ?p ref:hasTimeseriesId ?ts .
  ?p a brick:AirTemperatureSensor .
  ?z brick:hasPoint ?p .
  ?z rdfs:label ?zoneName .
}

